// Throwaway: proves the collapsed 0004 migration actually widened the CHECK
// (i.e. replace() matched, not a silent no-op) by inspecting the migrated
// schema text for late harnesses.
func TestThrowawayCollapsedHarnessCheck(t *testing.T) {
	dsn := "file:" + filepath.Join(t.TempDir(), "ao.db") + pragmas
	db, err := sql.Open("sqlite", dsn)
	if err != nil {
		t.Fatal(err)
	}
	defer db.Close()
	db.SetMaxOpenConns(1)
	if err := migrate(db); err != nil {
		t.Fatalf("migrate: %v", err)
	}
	var schema string
	if err := db.QueryRow(`SELECT sql FROM sqlite_master WHERE type='table' AND name='sessions'`).Scan(&schema); err != nil {
		t.Fatalf("read schema: %v", err)
	}
	for _, h := range []string{"autohand", "vibe", "kilocode", "agy", "grok"} {
		if !strings.Contains(schema, "'"+h+"'") {
			t.Fatalf("harness %q missing from CHECK — migration was a silent no-op.\nschema: %s", h, schema)
		}
	}
}

